(() => {
 const UI=window.PrototypeUI,C=window.PrototypeCapsules,D=window.PrototypeDates,R=window.PrototypeRecords,page=location.pathname.split('/').pop().slice(0,7),id=new URLSearchParams(location.search).get('id'),screen=document.querySelector('.screen');
 const home='m04-p12.html';document.querySelector('.back')?.addEventListener('click',()=>page==='m04-p13'?UI.back(home):UI.go(page==='m04-p12'?'m04-p01.html':home,{replace:true}));
 function missing(){screen.classList.add('prototype-capsule-missing');const box=UI.collectionState(C.key,{title:'这个胶囊已经不在了',action:'返回胶囊列表',fallback:home});box.classList.add('prototype-capsule-state');screen.append(box);}
 function invalidOpening(item){
  screen.classList.add('prototype-capsule-missing');
  const box=UI.components.state({kind:'error',title:'胶囊开启日期需要修正',message:item.name+'的信件和照片仍封存。选择有效日期后可以继续等待；修正日期不会自动开启。',action:'修正开启日期',onAction:()=>editOpening(item.id)});box.classList.add('prototype-capsule-state');screen.append(box);
 }
 async function editOpening(id){
  const current=C.find(id);if(!current||current.status!=='sealed'||C.days(current)!==null)return UI.go(location.href,{replace:true});
  const original=localStorage.getItem(C.key),form=document.createElement('form');form.className='prototype-capsule-date-form';form.noValidate=true;
  const field=UI.components.field({label:'新的开启日期',name:'opening',type:'date'});field.input.min=D.today().iso;
  const button=UI.components.button('保存开启日期');button.type='submit';form.append(field.root,button);const protect=UI.protectSheet(form);let cancelled=false;
  const beforeClose=()=>{cancelled=true;return protect.beforeClose();};
  form.onsubmit=event=>{event.preventDefault();const date=D.parse(field.input.value);if(!date||date.time<D.today().time){field.setError('请选择今天或未来的有效日期');field.input.focus();return;}cancelled=false;field.input.disabled=true;UI.busy(button,'保存中…',async()=>{if(cancelled||!C.reschedule(id,date.iso,original))return false;protect.commit();await UI.back(home);return UI.go(location.href,{replace:true});}).finally(()=>{field.input.disabled=false;});};
  return UI.sheet({title:'修正开启日期',message:'只修改开启日期，信件和照片保持封存。',content:form,actions:[],beforeClose});
 }
 if(page==='m04-p12'){
  document.querySelectorAll('.plus,.new').forEach(b=>b.onclick=()=>UI.go('m04-p13.html'));const cards=document.querySelector('.cards');cards.classList.add('prototype-capsule-cards');const tabs=document.querySelector('.tabs'),draft=document.createElement('button');draft.type='button';draft.setAttribute('role','tab');draft.textContent='草稿';tabs.append(draft);let selected='sealed',loading=false;
  function paint(){cards.replaceChildren();tabs.querySelectorAll('button').forEach((b,i)=>{const active=['sealed','opened','draft'][i]===selected;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});const values=C.all().filter(item=>item.status===selected).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));if(!values.length){const box=UI.components.state({title:selected==='sealed'?'还没有等待开启的胶囊':selected==='opened'?'还没有已经开启的胶囊':'还没有胶囊草稿',action:'写给未来的我们',onAction:()=>UI.go('m04-p13.html')});box.classList.add('prototype-capsule-empty');cards.append(box);}for(const item of values){const b=UI.components.card({content:[],onClick:()=>UI.go(C.route(item))});b.classList.add('prototype-capsule-card');const h=document.createElement('b'),meta=document.createElement('small');h.textContent=item.name||'未命名草稿';const days=C.days(item);meta.textContent=item.status==='draft'?'草稿 · 继续编辑':item.status==='opened'?'已开启':days===null?'请检查开启日期':days<=0?'可以开启了':item.opening+' · 还有 '+days+' 天';b.append(h,meta);cards.append(b);}}
  async function load(){if(loading)return;loading=true;cards.setAttribute('aria-busy','true');cards.replaceChildren(UI.components.loading({mode:'skeleton',label:'正在打开胶囊架…'}));await new Promise(r=>setTimeout(r,400));loading=false;cards.removeAttribute('aria-busy');if(UI.failNext('capsule-load')){cards.replaceChildren();cards.append(UI.components.state({kind:'error',title:'胶囊架暂时打不开',action:'重试加载胶囊',onAction:load}));}else paint();}
  tabs.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{selected=['sealed','opened','draft'][i];if(!loading)paint();});const refresh=document.createElement('button');refresh.className='prototype-capsule-refresh';refresh.textContent='↻';refresh.setAttribute('aria-label','刷新胶囊');refresh.onclick=load;screen.append(refresh);load();
 }
 if(page==='m04-p13'){
  const existing=id?C.find(id):null;if(id&&!existing){missing();return;}if(existing&&existing.status!=='draft'){UI.go(C.route(existing),{replace:true,force:true});return;}const form=document.querySelector('#capsule-form');form.elements.name.value=existing?.name||'';form.elements.message.value=existing?.message||'';form.elements.message.maxLength=2000;form.elements.opening.value=existing?.opening||D.add(D.today(),1).iso;form.elements.reminder.checked=existing?.reminder??true;let photo=existing?.photo||null,uploading=false;const file=document.querySelector('#photo');file.removeAttribute('multiple');const chosen=document.querySelector('#chosen');const slot=document.createElement('div');slot.className='prototype-capsule-photo-slot';slot.setAttribute('aria-hidden','true');form.append(slot);const preview=document.createElement('img');preview.className='prototype-capsule-preview';preview.alt='所选胶囊照片';form.append(preview);const remove=document.createElement('button');remove.type='button';remove.className='prototype-capsule-remove';remove.textContent='移除照片';form.append(remove);
  function paint(){preview.hidden=!photo;remove.hidden=!photo;if(photo)preview.src=photo;chosen.textContent=uploading?'正在读取照片…':photo?'1 张照片已选择':'可选 · 留下一张照片';}paint();const leave=UI.guard(form,{fallback:home,value:()=>JSON.stringify([form.elements.name.value,form.elements.message.value,form.elements.opening.value,form.elements.reminder.checked,photo,uploading]),onDiscard:()=>imageReader.cancel()});document.querySelector('.add-photo').onclick=()=>file.click();remove.onclick=()=>{photo=null;imageReader.cancel();file.value='';paint();};const imageReader=R.imageInput(file,'capsule-image',{onValue:value=>{photo=value;},onError:error=>UI.toast(error.message,'error'),onBusy:value=>{uploading=value;if(!value)file.value='';paint();}});
  form.elements.opening.readOnly=true;form.elements.opening.onclick=async()=>{const input=document.createElement('input');input.type='date';input.value=form.elements.opening.value;input.min=D.today().iso;input.setAttribute('aria-label','胶囊开启日期');const action=await UI.sheet({title:'开启日期',content:input,actions:[{label:'使用这个日期',value:'apply'}]});if(action==='apply'){if(!D.parse(input.value)){UI.fieldError(form.elements.opening,'请选择有效日期');return;}form.elements.opening.value=input.value;UI.fieldError(form.elements.opening,'');}};
  const buttons=[...form.querySelector('.actions').children];form.elements.name.addEventListener('input',()=>UI.fieldError(form.elements.name,''));form.elements.message.addEventListener('input',()=>UI.fieldError(form.elements.message,''));
  function save(status,button){if(buttons.some(b=>b.disabled))return;if(uploading){UI.toast('请等待照片读取完成');return;}const name=form.elements.name.value.trim(),message=form.elements.message.value.trim(),opening=form.elements.opening.value,date=D.parse(opening);if(status==='sealed'){const field=!name?form.elements.name:!message?form.elements.message:!date||date.time<D.today().time?form.elements.opening:null;if(field){UI.fieldError(field,field===form.elements.name?'请填写胶囊标题':field===form.elements.message?'请写下想留下的话':'请选择今天或未来的开启日期');field.focus();return;}}const other=buttons.find(b=>b!==button);other.disabled=true;UI.busy(button,status==='draft'?'暂存中…':'封存中…',()=>{if(UI.failNext('capsule-save'))throw new Error('胶囊未保存，请重试');const item={...existing,id:existing?.id||'capsule-'+crypto.randomUUID(),name,message,opening,reminder:form.elements.reminder.checked,photo,status,createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now()};if(!C.put(item))return false;return leave.complete(status==='draft'?home:C.route(item));}).finally(()=>{other.disabled=false;});}
  buttons[0].onclick=()=>save('draft',buttons[0]);form.addEventListener('submit',event=>{event.preventDefault();save('sealed',buttons[1]);});form.dataset.prototypeReady='true';
 }
 if(page==='m04-p14'||page==='m04-p15'){
  const item=C.find(id);if(!item){missing();return;}if((item.status==='opened')!==(page==='m04-p14')||item.status==='draft'){UI.go(C.route(item),{replace:true,force:true});return;}const more=document.createElement('button');more.id='more';more.className='prototype-capsule-more';more.setAttribute('aria-label','更多胶囊操作');more.textContent='•••';screen.append(more);more.onclick=async()=>{const action=await UI.sheet({title:'胶囊操作',actions:[{label:'删除胶囊',value:'delete',danger:true}]});if(action!=='delete'||!await UI.modal({title:'删除这个胶囊？',message:'这份信件和照片会从本地胶囊架移除。',confirm:'确认删除', danger: true,cancel:'取消'}))return;UI.busy(more,'删除中…',()=>{if(UI.failNext('capsule-delete'))throw new Error('删除未完成，请重试');if(!UI.write(C.key,C.all().filter(v=>v.id!==item.id)))return false;return UI.go(home,{force:true});});};
  if(page==='m04-p15'){const days=C.days(item);if(days===null){invalidOpening(item);return;}document.querySelector('.capsule-name').textContent=item.name;const counter=document.querySelector('.countdown');counter.replaceChildren();const strong=document.createElement('strong');strong.textContent=days===null?'日期异常':Math.max(0,days);counter.append(document.createTextNode(days!==null&&days>0?'还有 ':'等待开启 '),strong,document.createTextNode(days!==null&&days>0?' 天':''));document.querySelector('.opens').textContent='约定于 '+item.opening+' 开启';const reminder=document.querySelector('.reminder input');reminder.checked=item.reminder;reminder.onchange=()=>{const desired=reminder.checked;reminder.checked=item.reminder;UI.busy(reminder,'',()=>{if(!C.setReminder(item.id,desired))return false;item.reminder=desired;reminder.checked=desired;return true;});};if(days!==null&&days<=0){const open=document.createElement('button');open.className='prototype-capsule-open';open.textContent='打开这份心意';screen.append(open);document.querySelector('.hint').textContent='到了约定的日子，可以开启这份心意了';open.onclick=()=>UI.busy(open,'开启中…',()=>{const value=C.open(item.id);if(!value)return false;return UI.go(C.route(value),{replace:true,force:true});});}}
  else{document.querySelector('.letter-title').textContent=item.name;document.querySelector('.letter-body').textContent=item.message;const art=document.querySelector('.art-bottom');art.classList.add('prototype-capsule-photo-area');art.removeAttribute('role');art.removeAttribute('aria-label');if(item.photo){const img=document.createElement('img');img.src=item.photo;img.alt='封存时留下的照片';art.append(img);}else art.textContent='这份心意没有附照片';document.querySelector('#collect').onclick=()=>UI.busy(document.querySelector('#collect'),'收录中…',()=>{const momentId=C.collect(item.id);if(!momentId)return false;return UI.go('m04-p03.html?id='+encodeURIComponent(momentId),{force:true});});}
 }
})();
